/** GotSport-ish team / game export. Not Van colored sheets.
 *  Team Name + Division (or Home/Away + Game Date). Missing fields / dates /
 *  kids stay blank — never invented.
 */

import ExcelJS from "exceljs";
import { inferYear, parseHumanDate } from "../dates";
import { norm, type League, type Team, type TeamAdult } from "../model";
import { blankLeague, cellText } from "../parse";
import { fillCrowFlies, missingPieceIssues, structuralRefusals } from "../validate";
import type { IntakeAttempt } from "./types";

const COL = {
  team: ["team name", "team"],
  division: ["division", "age group", "agegroup"],
  home: ["home team", "home"],
  away: ["away team", "away"],
  "game date": ["game date", "match date", "game day", "date"],
  coach: ["coach name", "head coach", "coach"],
  "coach phone": ["coach phone", "coach phone number"],
  club: ["club name", "club", "association"],
  jersey: ["jersey", "color"],
  "player first": ["player first name", "player first"],
  "player last": ["player last name", "player last"],
  player: ["player name", "player"],
};

function headerKey(cell: string): string | null {
  const n = norm(cell);
  if (!n) return null;
  for (const [canon, aliases] of Object.entries(COL)) {
    if (canon === n || aliases.includes(n)) return canon;
  }
  return null;
}

function findGotSportHeader(ws: ExcelJS.Worksheet): { row: number; cols: Map<string, number> } | null {
  const maxRow = Math.min(ws.rowCount || 0, 25);
  const maxCol = Math.max(ws.columnCount || 0, 20);
  for (let r = 1; r <= maxRow; r++) {
    const cols = new Map<string, number>();
    for (let c = 1; c <= maxCol; c++) {
      const key = headerKey(cellText(ws.getRow(r).getCell(c)));
      if (key && !cols.has(key)) cols.set(key, c);
    }
    const teamish = cols.has("team") || (cols.has("home") && cols.has("away"));
    const soccer = cols.has("division") || cols.has("coach") || cols.has("game date") || (cols.has("home") && cols.has("away"));
    if (teamish && soccer && (cols.has("division") || cols.has("coach") || (cols.has("home") && cols.has("away")))) {
      return { row: r, cols };
    }
  }
  return null;
}

function take(ws: ExcelJS.Worksheet, r: number, cols: Map<string, number>, key: string): string {
  const c = cols.get(key);
  if (!c) return "";
  return cellText(ws.getRow(r).getCell(c));
}

function splitName(raw: string): TeamAdult {
  const parts = raw.trim().split(/\s+/);
  if (parts.length === 1) return { first: parts[0], last: "" };
  return { first: parts[0], last: parts.slice(1).join(" ") };
}

function bracketFromDivision(raw: string): string {
  const s = raw.trim();
  if (!s) return "";
  const girls = /girl/i.test(s);
  const m = s.match(/(\d+)\s*U/i);
  if (m) return girls ? `${m[1]}U Girls` : `${m[1]}U`;
  return s;
}

function playerName(ws: ExcelJS.Worksheet, r: number, cols: Map<string, number>): string {
  const full = take(ws, r, cols, "player");
  if (full) return full;
  return `${take(ws, r, cols, "player first")} ${take(ws, r, cols, "player last")}`.trim();
}

function upsertTeam(teams: Team[], next: Team) {
  const k = `${next.bracket} ${next.name}`.toLowerCase();
  const hit = teams.find((t) => `${t.bracket} ${t.name}`.toLowerCase() === k);
  if (!hit) {
    teams.push(next);
    return;
  }
  if (!hit.coach && next.coach) hit.coach = next.coach;
  if (next.coach?.phone && hit.coach && !hit.coach.phone) hit.coach.phone = next.coach.phone;
  if (!hit.association && next.association) hit.association = next.association;
  if (!hit.jersey && next.jersey) hit.jersey = next.jersey;
  for (const p of next.players) {
    if (p.name && !hit.players.some((x) => x.name.toLowerCase() === p.name.toLowerCase())) hit.players.push(p);
  }
}

function stubTeam(name: string, bracket: string, club: string, jersey: string, coachRaw: string, phone: string, kid: string): Team {
  const coach = coachRaw ? { ...splitName(coachRaw), phone: phone || undefined } : undefined;
  return {
    name,
    bracket,
    association: club,
    jersey,
    coach,
    players: kid ? [{ name: kid }] : [],
    willNotPlay: [],
    willNotTravelTo: [],
    awayDesired: 0,
    guestDesired: 0,
  };
}

function ensureAgeGroups(league: League) {
  for (const t of league.teams) {
    if (!t.bracket) continue;
    if (league.ageGroups.some((a) => a.name.toLowerCase() === t.bracket.toLowerCase())) continue;
    league.ageGroups.push({
      name: t.bracket,
      minOnField: null,
      maxOnField: null,
      gameLengthMinutes: null,
      assistantMin: null,
      assistantPreferred: null,
      fieldClasses: [],
      mayPlayWith: [t.bracket],
    });
  }
}

export function tryGotSportExport(wb: ExcelJS.Workbook, filename = ""): IntakeAttempt {
  const league = blankLeague();
  league.sourceName = filename || undefined;
  league.sampleOnly = false;
  const report: string[] = [];
  const dateIsos: string[] = [];
  const year = inferYear(filename, 2026);

  for (const ws of wb.worksheets) {
    const found = findGotSportHeader(ws);
    if (!found) continue;
    const maxRow = ws.rowCount || 0;
    for (let r = found.row + 1; r <= maxRow; r++) {
      const division = bracketFromDivision(take(ws, r, found.cols, "division"));
      const club = take(ws, r, found.cols, "club");
      const jersey = take(ws, r, found.cols, "jersey");
      const coachRaw = take(ws, r, found.cols, "coach");
      const phone = take(ws, r, found.cols, "coach phone");
      const kid = playerName(ws, r, found.cols);
      const named = take(ws, r, found.cols, "team");
      const home = take(ws, r, found.cols, "home");
      const away = take(ws, r, found.cols, "away");
      const dateRaw = take(ws, r, found.cols, "game date");
      if (dateRaw) {
        const iso = parseHumanDate(dateRaw, year);
        if (iso) dateIsos.push(iso);
      }
      const names = named ? [named] : [home, away].filter(Boolean);
      for (const name of names) {
        if (!name || headerKey(name)) continue;
        upsertTeam(
          league.teams,
          stubTeam(
            name,
            division,
            named ? club : "",
            named ? jersey : "",
            named ? coachRaw : "",
            named ? phone : "",
            named ? kid : "",
          ),
        );
      }
    }
  }

  if (!league.teams.length) {
    return { matched: false, strategy: "gotsport-export", reason: "no GotSport team or game columns" };
  }

  ensureAgeGroups(league);
  if (dateIsos.length) {
    dateIsos.sort();
    league.season.firstIso = dateIsos[0];
    league.season.lastIso = dateIsos[dateIsos.length - 1];
    league.season.firstRaw = dateIsos[0];
    league.season.lastRaw = dateIsos[dateIsos.length - 1];
  }
  league.travel = fillCrowFlies(league);

  const allStructural = structuralRefusals(league);
  const hard = allStructural.filter((i) => i.code !== "age-group-incomplete" && i.code !== "leftover-sample");
  const soft = allStructural
    .filter((i) => i.code === "age-group-incomplete" || i.code === "leftover-sample")
    .map((i) => ({ ...i, level: "flag" as const }));
  const issues = [...soft, ...missingPieceIssues(league)];
  report.push(`GotSport export: ${league.teams.length} teams read`);
  if (hard.length) {
    return {
      matched: true,
      strategy: "gotsport-export",
      result: { ok: false, league, issues: [...issues, ...hard], report, strategy: "gotsport-export" },
    };
  }
  return {
    matched: true,
    strategy: "gotsport-export",
    result: { ok: true, league, issues, report, strategy: "gotsport-export" },
  };
}
